 private static function lineAmount(string $quantity,string $rate):string{
  $values=[];foreach([$quantity,$rate]as$value){if(!preg_match('/^([0-9]{1,13})(?:\.([0-9]{1,2}))?$/D',$value,$m))throw new DomainException('company_portal_invoice_unavailable');$values[]=ltrim($m[1].str_pad($m[2]??'',2,'0'),'0')?:'0';}
  [$left,$right]=$values;$digits=array_fill(0,strlen($left)+strlen($right),0);for($i=strlen($left)-1;$i>=0;$i--)for($j=strlen($right)-1;$j>=0;$j--)$digits[$i+$j+1]+=(int)$left[$i]*(int)$right[$j];for($k=count($digits)-1;$k>0;$k--){$digits[$k-1]+=intdiv($digits[$k],10);$digits[$k]%=10;}
  $raw=ltrim(implode('',$digits),'0')?:'0';$raw=str_pad($raw,3,'0',STR_PAD_LEFT);$carry=50;for($i=strlen($raw)-1;$i>=0&&$carry>0;$i--){$v=(int)$raw[$i]+$carry;$raw[$i]=(string)($v%10);$carry=intdiv($v,10);}if($carry)$raw=$carry.$raw;$minor=ltrim(substr($raw,0,-2),'0')?:'0';$minor=str_pad($minor,3,'0',STR_PAD_LEFT);return (ltrim(substr($minor,0,-2),'0')?:'0').'.'.substr($minor,-2);
 }
 private function tables():array{$tables=['issuers_lock','issuers_registry','issuers_installation_identity','issuers_clients','clients','contacts','contact_permissions','options','invoices','currencies','countries','itemable','item_tax','invoicepaymentrecords','credits','issuers_audit'];foreach(['files','creditnotes','company_credit_entries','company_bank_receipt_reversals','company_asaas_refund_postings']as$name)if($this->db->table_exists($this->p.$name))$tables[]=$name;return$tables;}
 private function readInOwned(array $binding,int $issuer,int $id,string $hash):array{
  IssuerTransaction::assertOwned($this->db,$this->p,$this->tables());$who=$this->portal->invoiceIdentity($binding,$issuer,true);if(!$who||(new IssuerResourceAccess($this->db,$this->p))->primaryId()!==$issuer||$this->rows('SELECT client_id FROM '.$this->p.'issuers_clients WHERE client_id=?',[$who['client_id']]))throw new DomainException('company_portal_invoice_unavailable');
  $verified=$this->rows('SELECT email_verified_at FROM '.$this->p.'contacts WHERE id=? AND userid=?',[$who['contact_id'],$who['client_id']]);$grants=$this->rows('SELECT permission_id FROM '.$this->p.'contact_permissions WHERE userid=? AND permission_id=1',[$who['contact_id']]);if(count($verified)!==1||$verified[0]['email_verified_at']===null||count($grants)!==1)throw new DomainException('company_portal_invoice_unavailable');
  $rows=$this->rows('SELECT i.*,c.company client_name,c.vat client_tax_id,m.name currency_name,r.legal_name,r.tax_id issuer_tax_id FROM '.$this->p.'invoices i JOIN '.$this->p.'clients c ON c.userid=i.clientid JOIN '.$this->p.'currencies m ON m.id=i.currency JOIN '.$this->p.'issuers_registry r ON r.id=? WHERE i.id=? AND i.issuer_id IS NULL AND i.clientid=? FOR UPDATE',[$issuer,$id,$who['client_id']]);if(count($rows)!==1||!is_string($rows[0]['hash'])||!hash_equals($rows[0]['hash'],$hash))throw new DomainException('company_portal_invoice_unavailable');$row=$rows[0];$status=(int)$row['status'];$settings=new CompanySettingsStorage($this->db,$this->p);$exclude=$settings->exists($issuer,'exclude_invoice_from_client_area_with_draft_status')?$settings->get($issuer,'exclude_invoice_from_client_area_with_draft_status'):'0';if(!in_array($exclude,['0','1'],true)||!in_array($status,[1,2,3,4,5,6],true)||($status===6&&$exclude==='1'))throw new DomainException('company_portal_invoice_unavailable');
  $padding=$settings->exists($issuer,'number_padding_prefixes')?$settings->get($issuer,'number_padding_prefixes'):'0';if(!preg_match('/^(?:[0-9]|1[0-9]|20)$/D',(string)$padding))throw new DomainException('company_portal_invoice_unavailable');$number=$status===6?$row['prefix'].'DRAFT':SalesNumberPresentation::format($row['number'],$row['number_format'],$row['prefix'],$row['date'],(int)$padding);
  foreach(['company_credit_entries','company_bank_receipt_reversals','company_asaas_refund_postings']as$table)if($this->db->table_exists($this->p.$table)){if(!IssuerStorage::fieldExists($this->db,'invoice_id',$this->p.$table)||$this->rows('SELECT invoice_id FROM '.$this->p.$table.' WHERE invoice_id=? LIMIT 1 FOR UPDATE',[$id]))throw new DomainException('company_portal_invoice_unavailable');}
