  $lines=[];foreach($items as$item){if(!in_array((string)$item['is_optional'],['0','1'],true)||!in_array((string)$item['is_selected'],['0','1'],true))throw new DomainException('company_portal_invoice_unavailable');if((string)$item['is_optional']==='1'&&(string)$item['is_selected']!=='1')continue;$qty=(string)$item['qty'];$rate=(string)$item['rate'];$amount=self::lineAmount($qty,$rate);$taxes=[];foreach($this->rows("SELECT taxname,taxrate FROM {$this->p}item_tax WHERE itemid=? AND rel_id=? AND rel_type='invoice' ORDER BY id",[$item['id'],$id])as$tax)$taxes[]=['name'=>(string)$tax['taxname'],'rate'=>(string)$tax['taxrate']];$lines[]=['description'=>(string)$item['description'],'details'=>(string)($item['long_description']??''),'quantity'=>$qty,'rate'=>$rate,'amount'=>$amount,'unit'=>(string)($item['unit']??''),'taxes'=>$taxes];}
  $addresses=[];foreach(['billing','shipping']as$kind){$address=[];foreach(['street','city','state','zip']as$field)$address[$field]=(string)($row[$kind.'_'.$field]??'');$country=$row[$kind.'_country']??null;$address['country']='';if($country!==null&&(string)$country!==''&&(string)$country!=='0'){$found=$this->rows('SELECT short_name FROM '.$this->p.'countries WHERE country_id=?',[$country]);if(count($found)!==1)throw new DomainException('company_portal_invoice_unavailable');$address['country']=(string)$found[0]['short_name'];}$addresses[$kind]=$address;}if((string)($row['include_shipping']??'0')!=='1'||(string)($row['show_shipping_on_invoice']??'0')!=='1')$addresses['shipping']=null;
  $document=['invoice_id'=>$id,'issuer_id'=>$issuer,'number'=>$number,'identity'=>['legal_name'=>(string)$row['legal_name'],'tax_id'=>(string)($row['issuer_tax_id']??'')],'recipient'=>['name'=>(string)$row['client_name'],'tax_id'=>(string)($row['client_tax_id']??''),'billing'=>$addresses['billing'],'shipping'=>$addresses['shipping']],'currency'=>(string)$row['currency_name'],'date'=>(string)$row['date'],'due_date'=>$row['duedate']?:null,'status'=>$status,'items'=>$lines,'totals'=>[],'position'=>['received'=>CompanyInvoiceAmounts::decimal($paid),'receivable'=>CompanyInvoiceAmounts::decimal($total-$paid-$applied)],'note'=>(string)($row['clientnote']??''),'terms'=>(string)($row['terms']??'')];foreach(['subtotal','total_tax','discount_total','adjustment','total']as$field)$document['totals'][$field]=(string)($row[$field]??'0');
  if($this->portal->invoiceIdentity($binding,$issuer,true)!==$who||(new IssuerResourceAccess($this->db,$this->p))->primaryId()!==$issuer||$this->rows('SELECT client_id FROM '.$this->p.'issuers_clients WHERE client_id=?',[$who['client_id']]))throw new DomainException('company_portal_invoice_unavailable');return['document'=>$document,'payments'=>$payments];
 }
 public function read(array$binding,int$issuer,int$id,string$hash):array{return IssuerTransaction::run($this->db,$this->p,$this->tables(),fn()=>$this->readInOwned($binding,$issuer,$id,$hash));}
 /** Native file references are exposed only after the same historical parent is authorized. */
 public function attachments(array$binding,int$issuer,int$id,string$hash):array{
  return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash):array{$before=$this->readInOwned($binding,$issuer,$id,$hash);if(!$this->db->table_exists($this->p.'files'))return[];
   $rows=$this->rows("SELECT id,file_name,attachment_key,external,external_link FROM {$this->p}files WHERE rel_type='invoice' AND rel_id=? AND visible_to_customer=1 ORDER BY id LIMIT 101",[$id]);if(count($rows)>100)throw new DomainException('company_portal_invoice_unavailable');$result=[];require_once __DIR__.'/NativeCompanyFileContent.php';foreach($rows as$row){if(!is_string($row['file_name'])||$row['file_name']===''||strlen($row['file_name'])>191||preg_match('/[\x00-\x1f\x7f]/',$row['file_name']))throw new DomainException('company_portal_invoice_unavailable');$external=(string)($row['external']??'');if($external!==''){$url=NativeCompanyFileContent::external($external,(string)$row['external_link']);$result[]=['filename'=>$row['file_name'],'external'=>$url,'key'=>null];}else{if(!is_string($row['attachment_key'])||!preg_match('/^[a-f0-9]{32}$/D',$row['attachment_key']))throw new DomainException('company_portal_invoice_unavailable');$result[]=['filename'=>$row['file_name'],'external'=>null,'key'=>$row['attachment_key']];}}if($this->readInOwned($binding,$issuer,$id,$hash)!==$before)throw new DomainException('company_portal_invoice_unavailable');return$result;
  });
 }
 public function file(array$binding,int$issuer,int$id,string$hash,string$key):array{
  if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('company_portal_invoice_unavailable');return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash,$key):array{$before=$this->readInOwned($binding,$issuer,$id,$hash);if(!$this->db->table_exists($this->p.'files'))throw new DomainException('company_portal_invoice_unavailable');$rows=$this->rows("SELECT id,file_name,external FROM {$this->p}files WHERE rel_type='invoice' AND rel_id=? AND attachment_key=? AND visible_to_customer=1 FOR UPDATE",[$id,$key]);if(count($rows)!==1||!empty($rows[0]['external']))throw new DomainException('company_portal_invoice_unavailable');require_once __DIR__.'/NativeCompanyLegacyInvoiceContent.php';$content=NativeCompanyLegacyInvoiceContent::read($id,(string)$rows[0]['file_name']);$content['filename']=$rows[0]['file_name'];if($this->readInOwned($binding,$issuer,$id,$hash)!==$before)throw new DomainException('company_portal_invoice_unavailable');$metadata=json_encode(['contact_id'=>$binding['contact_id'],'client_id'=>$binding['client_id'],'file_id'=>(int)$rows[0]['id'],'sha256'=>$content['content_hash'],'receipt'=>bin2hex(random_bytes(16))],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(0,?,?,?,?,?)',['native_portal_legacy_invoice_file_downloaded',$issuer,$id,date('Y-m-d H:i:s'),$metadata]);$audit=(int)$this->db->insert_id();if(count($this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND subject_id=? AND metadata_json=?',[$audit,$issuer,$id,$metadata]))!==1)throw new RuntimeException('issuer_portal_write_unconfirmed');return$content;});
 }
 public function confirm(array$binding,int$issuer,int$id,string$hash,array$before,string$contentHash,?int$payment):void{
  if(!preg_match('/^[a-f0-9]{64}$/D',$contentHash))throw new DomainException('company_portal_invoice_unavailable');IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($binding,$issuer,$id,$hash,$before,$contentHash,$payment):void{
   $after=$this->readInOwned($binding,$issuer,$id,$hash);if($after!==$before)throw new DomainException('company_portal_invoice_unavailable');if($payment!==null&&count(array_filter($after['payments'],static fn($row)=>$row['id']===$payment))!==1)throw new DomainException('company_portal_invoice_unavailable');
   $event=$payment===null?'native_portal_legacy_invoice_pdf_downloaded':'native_portal_legacy_payment_receipt_downloaded';$metadata=json_encode(['contact_id'=>$binding['contact_id'],'client_id'=>$binding['client_id'],'payment_id'=>$payment,'sha256'=>$contentHash,'receipt'=>bin2hex(random_bytes(16))],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(0,?,?,?,?,?)',[$event,$issuer,$id,date('Y-m-d H:i:s'),$metadata]);$audit=(int)$this->db->insert_id();if(count($this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND subject_id=? AND event=? AND metadata_json=?',[$audit,$issuer,$id,$event,$metadata]))!==1)throw new RuntimeException('issuer_portal_write_unconfirmed');
  });
